315→func TestHandleLifecycleCompaction_PreservesTranscriptOffset(t *testing.T) {
316→	// Cannot use t.Parallel() because we use t.Chdir()
317→	tmpDir := t.TempDir()
318→	t.Chdir(tmpDir)
319→
320→	// Initialize git repo with a commit (not empty)
321→	setupGitRepoWithCommit(t, tmpDir)
322→	paths.ClearWorktreeRootCache()
323→
324→	// Create .entire directory structure
325→	if err := os.MkdirAll(paths.EntireDir, 0o755); err != nil {
326→		t.Fatalf("Failed to create .entire: %v", err)
327→	}
328→
329→	// Create a transcript file
330→	transcriptPath := filepath.Join(tmpDir, "transcript.jsonl")
331→	transcriptContent := `{"type":"user","message":{"role":"user","content":"test prompt"}}` + "\n"
332→	if err := os.WriteFile(transcriptPath, []byte(transcriptContent), 0o644); err != nil {
333→		t.Fatalf("Failed to create transcript: %v", err)
334→	}
335→
336→	sessionID := "compaction-test-session"
337→
338→	// Create session state with non-zero transcript offset (set by prior condensation)
339→	sessionState := &strategy.SessionState{
340→		SessionID:                 sessionID,
341→		StartedAt:                 time.Now(),
342→		CheckpointTranscriptStart: 50,
343→	}
344→	if err := strategy.SaveSessionState(context.Background(), sessionState); err != nil {
345→		t.Fatalf("Failed to save session state: %v", err)
346→	}
347→
348→	ag := newMockAgent()
349→	event := &agent.Event{
350→		Type:       agent.Compaction,
351→		SessionID:  sessionID,
352→		SessionRef: transcriptPath,
353→	}
354→
355→	// Compaction should NOT reset the transcript offset.
356→	// Many agents (e.g., Gemini) fire pre-compress as a no-op after every tool call;
357→	// resetting the offset causes stale files to re-appear in carry-forward.
358→	err := handleLifecycleCompaction(context.Background(), ag, event)
359→	if err != nil {
360→		t.Logf("handleLifecycleCompaction returned error (expected in minimal test): %v", err)
361→	}
362→
363→	// Verify CheckpointTranscriptStart was preserved (not reset to 0)
364→	loadedState, loadErr := strategy.LoadSessionState(context.Background(), sessionID)
365→	if loadErr != nil {
366→		t.Fatalf("Failed to load session state after compaction: %v", loadErr)
367→	}
368→	require.NotNil(t, loadedState, "Session state is nil after compaction")
369→	if loadedState.CheckpointTranscriptStart != 50 {
370→		t.Errorf("CheckpointTranscriptStart = %d, want 50 (compaction should preserve offset)",
371→			loadedState.CheckpointTranscriptStart)
372→	}
373→}
