285→// GitIsolatedEnv returns os.Environ() with git isolation variables set.
286→// This prevents user/system git config (global gitignore, aliases, etc.) from
287→// affecting test behavior. Use this for any exec.Command that runs git or the
288→// CLI binary in integration tests.
289→//
290→// See https://git-scm.com/docs/git#Documentation/git.txt-GITCONFIGGLOBAL
291→//
292→// Existing GIT_CONFIG_GLOBAL/GIT_CONFIG_SYSTEM entries are filtered out before
293→// appending overrides to ensure they take effect regardless of parent env.
294→func GitIsolatedEnv() []string {
295→	env := os.Environ()
296→	filtered := make([]string, 0, len(env)+2)
297→	for _, e := range env {
298→		if strings.HasPrefix(e, "GIT_CONFIG_GLOBAL=") || strings.HasPrefix(e, "GIT_CONFIG_SYSTEM=") {
299→			continue
300→		}
301→		filtered = append(filtered, e)
302→	}
303→	return append(filtered,
304→		"GIT_CONFIG_GLOBAL=/dev/null", // Isolate from user's global git config (e.g. global gitignore)
305→		"GIT_CONFIG_SYSTEM=/dev/null", // Isolate from system git config
306→	)
307→}
