399→func TestHandleLifecycleCompaction_PreservesTranscriptOffset(t *testing.T) {
400→	// Cannot use t.Parallel() because we use t.Chdir()
401→	tmpDir := t.TempDir()
402→	t.Chdir(tmpDir)
403→
404→	// Initialize git repo with a commit (not empty)
405→	setupGitRepoWithCommit(t, tmpDir)
406→	paths.ClearWorktreeRootCache()
407→
408→	// Create .entire directory structure
409→	if err := os.MkdirAll(paths.EntireDir, 0o755); err != nil {
410→		t.Fatalf("Failed to create .entire: %v", err)
411→	}
412→
413→	// Create a transcript file
414→	transcriptPath := filepath.Join(tmpDir, "transcript.jsonl")
415→	transcriptContent := `{"type":"user","message":{"role":"user","content":"test prompt"}}` + "\n"
416→	if err := os.WriteFile(transcriptPath, []byte(transcriptContent), 0o644); err != nil {
417→		t.Fatalf("Failed to create transcript: %v", err)
418→	}
419→
420→	sessionID := "compaction-test-session"
421→
422→	// Create session state with non-zero transcript offset (set by prior condensation)
423→	sessionState := &strategy.SessionState{
424→		SessionID:                 sessionID,
425→		StartedAt:                 time.Now(),
426→		CheckpointTranscriptStart: 50,
427→	}
428→	if err := strategy.SaveSessionState(context.Background(), sessionState); err != nil {
429→		t.Fatalf("Failed to save session state: %v", err)
430→	}
431→
432→	ag := newMockAgent()
433→	event := &agent.Event{
434→		Type:       agent.Compaction,
435→		SessionID:  sessionID,
436→		SessionRef: transcriptPath,
437→	}
438→
439→	// Compaction should NOT reset the transcript offset.
440→	// Many agents (e.g., Gemini) fire pre-compress as a no-op after every tool call;
441→	// resetting the offset causes stale files to re-appear in carry-forward.
442→	err := handleLifecycleCompaction(context.Background(), ag, event)
443→	if err != nil {
444→		t.Logf("handleLifecycleCompaction returned error (expected in minimal test): %v", err)
445→	}
446→
447→	// Verify CheckpointTranscriptStart was preserved (not reset to 0)
448→	loadedState, loadErr := strategy.LoadSessionState(context.Background(), sessionID)
449→	if loadErr != nil {
450→		t.Fatalf("Failed to load session state after compaction: %v", loadErr)
451→	}
452→	require.NotNil(t, loadedState, "Session state is nil after compaction")
453→	if loadedState.CheckpointTranscriptStart != 50 {
454→		t.Errorf("CheckpointTranscriptStart = %d, want 50 (compaction should preserve offset)",
455→			loadedState.CheckpointTranscriptStart)
456→	}
457→}
