629→// setupGitRepoWithCommit initializes a git repo with an initial commit.
630→func setupGitRepoWithCommit(t *testing.T, dir string) {
631→	t.Helper()
632→
633→	// Initialize git repo
634→	if err := os.MkdirAll(filepath.Join(dir, ".git", "objects"), 0o755); err != nil {
635→		t.Fatalf("Failed to create .git/objects: %v", err)
636→	}
637→	if err := os.MkdirAll(filepath.Join(dir, ".git", "refs", "heads"), 0o755); err != nil {
638→		t.Fatalf("Failed to create .git/refs/heads: %v", err)
639→	}
640→	if err := os.WriteFile(filepath.Join(dir, ".git", "HEAD"), []byte("ref: refs/heads/main\n"), 0o644); err != nil {
641→		t.Fatalf("Failed to create HEAD: %v", err)
642→	}
643→
644→	// Create a dummy file to commit
645→	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("# Test\n"), 0o644); err != nil {
646→		t.Fatalf("Failed to create README.md: %v", err)
647→	}
648→
649→	// Use go-git to create an initial commit
650→	repo, err := strategy.OpenRepository(context.Background())
651→	if err != nil {
652→		// If we can't open with go-git, the empty repo check will work differently
653→		t.Logf("Note: Could not open repository with go-git: %v", err)
654→		return
655→	}
656→
657→	wt, err := repo.Worktree()
658→	if err != nil {
659→		t.Logf("Note: Could not get worktree: %v", err)
660→		return
661→	}
662→
663→	if _, err := wt.Add("README.md"); err != nil {
664→		t.Logf("Note: Could not add file: %v", err)
665→		return
666→	}
667→
668→	if _, err := wt.Commit("Initial commit", &git.CommitOptions{
669→		Author: &object.Signature{
670→			Name:  "Test",
671→			Email: "test@test.com",
672→			When:  time.Now(),
