 37→func TestPreTaskStateFile(t *testing.T) {
 38→	toolUseID := "toolu_abc123"
 39→	// preTaskStateFile returns an absolute path within the repo
 40→	// Verify it ends with the expected relative path suffix
 41→	expectedSuffix := filepath.Join(paths.EntireTmpDir, "pre-task-toolu_abc123.json")
 42→	got := preTaskStateFile(context.Background(), toolUseID)
 43→	if !filepath.IsAbs(got) {
 44→		// If we're not in a git repo, it falls back to relative paths
 45→		if got != expectedSuffix {
 46→			t.Errorf("preTaskStateFile() = %v, want %v", got, expectedSuffix)
 47→		}
 48→	} else {
 49→		// When in a git repo, the path should end with the expected suffix
 50→		if !hasSuffix(got, expectedSuffix) {
 51→			t.Errorf("preTaskStateFile() = %v, should end with %v", got, expectedSuffix)
 52→		}
 53→	}
 54→}
