1029→// computeDiffStats computes added and removed line counts between old and new content.
1030→// Uses a simple line-based diff algorithm.
1031→func computeDiffStats(oldContent, newContent []byte) (added, removed int) {
1032→	oldLines := splitLines(oldContent)
1033→	newLines := splitLines(newContent)
1034→
1035→	// Build a set of old lines with counts
1036→	oldSet := make(map[string]int)
1037→	for _, line := range oldLines {
1038→		oldSet[line]++
1039→	}
1040→
1041→	// Check which new lines are truly new
1042→	for _, line := range newLines {
1043→		if oldSet[line] > 0 {
1044→			oldSet[line]--
1045→		} else {
1046→			added++
1047→		}
1048→	}
1049→
1050→	// Remaining old lines are removed
1051→	for _, count := range oldSet {
1052→		removed += count
1053→	}
1054→
1055→	return added, removed
1056→}
